	if err != nil {
		t.Fatalf("first InstallHooks() error = %v", err)
	}

	// Second install should add 0 hooks
	count, err := agent.InstallHooks(true, false)
	if err != nil {
		t.Fatalf("second InstallHooks() error = %v", err)
	}
	if count != 0 {
		t.Errorf("second InstallHooks() count = %d, want 0 (idempotent)", count)
	}
}

func TestInstallHooks_LocalDev_Uninstall(t *testing.T) {
	tempDir := t.TempDir()
	t.Chdir(tempDir)

	agent := &ClaudeCodeAgent{}

	// Install with localDev
	_, err := agent.InstallHooks(true, false)
	if err != nil {
		t.Fatalf("InstallHooks() error = %v", err)
	}

	// Uninstall should remove wrapper hooks
	err = agent.UninstallHooks()
	if err != nil {
		t.Fatalf("UninstallHooks() error = %v", err)
	}

	if agent.AreHooksInstalled() {
		t.Error("wrapper hooks should not be installed after uninstall")
	}
}

