func verifyClaudeHookCommand(t *testing.T, matchers []ClaudeHookMatcher, matcherName, expectedCommand string) {
	t.Helper()
	for _, matcher := range matchers {
		if matcher.Matcher == matcherName {
			for _, hook := range matcher.Hooks {
				if hook.Command == expectedCommand {
					return
				}
			}
		}
	}
	t.Errorf("hook with matcher=%q command=%q not found", matcherName, expectedCommand)
}

func verifyClaudeHookCommandWithMatcher(t *testing.T, matchers []ClaudeHookMatcher, matcherName, expectedCommand string) {
	t.Helper()
	verifyClaudeHookCommand(t, matchers, matcherName, expectedCommand)
}
